namespace AssetTracker.Models;

/// <summary>
/// Represents a person who can be assigned assets (the Employee table). SqlEmployeeRepository creates these from database rows, and the form shows them in the "assigned to" dropdown.
/// </summary>

public class Employee
{

    /// Primary key, generated by the database (IDENTITY).

    public int EmployeeId { get; set; }
    public string FirstName { get; set; } = "";
    public string LastName { get; set; } = "";
    public string EmailAddress { get; set; } = "";

    /// Foreign key to Department. Stored as an ID rather than a Department object.

    public int DepartmentId { get; set; }


    /// Controls how an Employee appears when placed in a ComboBox.WinForms calls ToString() to get the text for each item, so the dropdown shows "Aileen MacLeod" instead of "AssetTracker.Models.Employee". The selected item is still the full Employee object, so the form can read its EmployeeId when saving.

    public override string ToString() => $"{FirstName} {LastName}";
}